template.query:
query AnalyzeQueryPerformanceWithParams($timeRange: String!, $queryTypes: [String!], $threshold: Float) {
  analyzeQueryPerformance(timeRange: $timeRange, queryTypes: $queryTypes, slowQueryThreshold: $threshold) {
    summary {
      totalQueries
      avgExecutionTime
      slowQueries
      fastQueries
      errorRate
    }
    slowQueries {
      query
      avgExecutionTime
      executionCount
      lastExecuted
      optimization {
        suggestions
        expectedImprovement
        complexity
      }
    }
    patterns {
      peakHours
      commonPatterns
      bottlenecks
    }
    recommendations {
      indexSuggestions {
        table
        columns
        estimatedImprovement
        creationCost
      }
      queryOptimizations {
        original
        optimized
        improvement
      }
      cacheStrategies {
        queries
        ttl
        hitRate
      }
    }
  }
}
